<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{ArrowLeft,Database,FolderTree,Plus,Save,Trash2,Upload}from'lucide-vue-next';import{api}from'../api';import{useAppStore}from'../stores/app';import type{ManualNode,Output,Upstream}from'../types';
const TEMPLATE='{index}|{flag}|{name}|{traffic}|{reset}',route=useRoute(),router=useRouter(),store=useAppStore(),saving=ref(false),manualContent=ref(''),manualNodes=ref<ManualNode[]>([]),editing=computed(()=>!!route.params.id);const model=reactive({name:'我的订阅组',note:'',interval_minutes:30,enabled:true,rename_mode:'passthrough' as 'passthrough'|'smart',rename_ignore:'',rename_template:TEMPLATE,upstreams:[]as Upstream[],outputs:[{client_type:'mihomo',name:'我的订阅',slug:'mihomo',update_interval_minutes:60,enabled:true}]as Output[]});
function blankUpstream():Upstream{return{name:`订阅链接 ${model.upstreams.length+1}`,url:'',enabled:true,rename_policy:'inherit',rename_ignore:'',rename_template:TEMPLATE,last_bytes:0,node_count:0,filtered_count:0,used_cache:false}}function addUpstream(){model.upstreams.push(blankUpstream())}function addOutput(){const type=store.settings?.default_client_type||'mihomo';let slug=type,n=2;while(model.outputs.some(x=>x.slug===slug))slug=type+n++;model.outputs.push({client_type:type,name:model.name,slug,update_interval_minutes:60,enabled:true})}
onMounted(async()=>{if(!store.settings)await store.load();if(editing.value){const data:any=await api(`/api/subscriptions/${route.params.id}`);Object.assign(model,data);for(const upstream of model.upstreams){if(upstream.rename_policy==='passthrough')upstream.rename_policy='disabled'}manualNodes.value=data.manual_nodes||[]}else{model.interval_minutes=store.settings!.default_refresh_interval_minutes;model.outputs[0].client_type=store.settings!.default_client_type;model.outputs[0].slug=store.settings!.default_client_type;model.outputs[0].update_interval_minutes=store.settings!.default_output_interval_minutes}})
async function save(){if(!model.upstreams.some(x=>x.enabled)&&!manualNodes.value.some(x=>x.enabled)&&!manualContent.value.trim()){ElMessage.warning('至少添加一条订阅链接或一条手动节点');return}saving.value=true;try{const payload={...model,upstreams:model.upstreams.filter(x=>x.url).map(({id,name,url,enabled,rename_policy,rename_ignore,rename_template})=>({id,name,url,enabled,rename_policy,rename_ignore,rename_template})),outputs:model.outputs.map(({id,client_type,name,slug,update_interval_minutes,enabled})=>({id,client_type,name,slug,update_interval_minutes,enabled}))};const result:any=await api(editing.value?`/api/subscriptions/${route.params.id}`:'/api/subscriptions',{method:editing.value?'PUT':'POST',body:JSON.stringify(payload)});const groupId=result.id||Number(route.params.id);if(manualContent.value.trim())await api(`/api/subscriptions/${groupId}/manual-nodes/import`,{method:'POST',body:JSON.stringify({content:manualContent.value})});ElMessage.success('节点来源与输出已保存');await store.loadGroups();router.push(`/groups/${groupId}/detail`)}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}
async function toggleManual(node:ManualNode,value:unknown){const result:any=await api(`/api/subscriptions/${route.params.id}/manual-nodes/${node.id}`,{method:'PUT',body:JSON.stringify({enabled:!!value})});manualNodes.value=result.nodes}async function deleteManual(node:ManualNode){try{await ElMessageBox.confirm(`删除手动节点“${node.name}”？`,'删除节点',{type:'warning'});const result:any=await api(`/api/subscriptions/${route.params.id}/manual-nodes/${node.id}`,{method:'DELETE'});manualNodes.value=result.nodes}catch{}}
</script>
<template><section class="page editor-page"><header class="page-head"><div><button class="back" @click="router.back()"><ArrowLeft/></button><p class="eyebrow">NODE SOURCES</p><h1>{{editing?'编辑订阅组':'新建订阅组'}}</h1><p>订阅链接和手动节点可混合使用，标准化后统一改名、分类、输出和测活。</p></div><div class="head-actions"><el-button v-if="editing" @click="router.push(`/groups/${route.params.id}/categories`)"><FolderTree/>分类管理</el-button><el-button type="primary" :loading="saving" @click="save"><Save/>保存</el-button></div></header><div class="editor-layout"><div class="editor-main"><section class="panel form-section"><div class="section-head"><span>01</span><div><h2>基本信息</h2><p>识别和调度这个订阅组。</p></div></div><div class="form-grid"><label>名称<el-input v-model="model.name"/></label><label>刷新间隔（分钟）<el-input-number v-model="model.interval_minutes" :min="5" :max="10080"/></label><label class="wide">备注<el-input v-model="model.note"/></label></div><el-switch v-model="model.enabled" active-text="启用订阅组"/></section>
<section class="panel form-section"><div class="section-head"><span>02</span><div><h2>远程订阅链接</h2><p>每条链接只请求一次，并可单独决定是否参与自动改名。</p></div><el-button @click="addUpstream"><Plus/>添加链接</el-button></div><div v-if="!model.upstreams.length" class="mini-empty">当前没有远程链接，可以只使用手动节点。</div><div class="structured-list upstream-config-list"><article v-for="(u,i) in model.upstreams" :key="u.id||i"><div class="upstream-main-row"><div class="list-fields"><label>来源名称<el-input v-model="u.name"/></label><label class="url-field">订阅 URL<el-input v-model="u.url" type="password" show-password/></label></div><el-switch v-model="u.enabled"/><button class="icon-danger" @click="model.upstreams.splice(i,1)"><Trash2/></button></div><div class="upstream-rename-row"><label>自动改名<el-select v-model="u.rename_policy"><el-option label="继承订阅组规则" value="inherit"/><el-option label="关闭（保留上游原名）" value="disabled"/><el-option label="使用独立智能规则" value="smart"/></el-select><small class="field-help">选择关闭后，这条订阅不会应用本组自动改名规则。已有“原样透传”配置仍兼容。</small></label><template v-if="u.rename_policy==='smart'"><label>忽略前缀<el-input v-model="u.rename_ignore" placeholder="例如 DMIT-US"/></label><label class="wide">独立模板<el-input v-model="u.rename_template"/></label></template></div></article></div></section>
<section class="panel form-section"><div class="section-head"><span>03</span><div><h2>手动节点</h2><p>手动节点默认保留导入名称，不参与订阅组自动改名；导入后可在节点详情中逐个设置名称。</p></div><Database/></div><div class="manual-rename-notice">手动节点：自动改名已固定关闭 · 单节点自定义名称仍然优先</div><el-input v-model="manualContent" type="textarea" :rows="6" placeholder="粘贴 vless://、vmess://、trojan://… 或 proxies: YAML；可一次导入多条"/><div v-if="manualNodes.length" class="manual-node-list"><article v-for="n in manualNodes" :key="n.id"><span><b>{{n.name}}</b><small>{{n.protocol.toUpperCase()}} · 连接参数已加密</small></span><span class="manual-current-name"><small>当前节点名</small><b>{{n.final_name||n.name}}</b></span><el-switch :model-value="n.enabled" @change="toggleManual(n,$event)"/><el-button link type="danger" @click="deleteManual(n)">删除</el-button></article></div></section>
<section class="panel form-section"><div class="section-head"><span>04</span><div><h2>订阅组默认改名</h2><p>仅作用于选择“继承订阅组规则”的远程链接；手动节点始终不参与。</p></div></div><el-radio-group v-model="model.rename_mode"><el-radio-button value="passthrough">原样透传</el-radio-button><el-radio-button value="smart">智能规则</el-radio-button></el-radio-group><div v-if="model.rename_mode==='smart'" class="form-grid rename-config"><label>忽略前缀<el-input v-model="model.rename_ignore" type="textarea" :rows="3"/></label><label>模板<el-input v-model="model.rename_template"/><small class="field-help">{index} {flag} {name} {traffic} {reset} {source}</small></label></div></section>
<section class="panel form-section"><div class="section-head"><span>05</span><div><h2>客户端输出</h2><p>Mihomo 支持自定义代理分类；旧客户端只输出兼容节点。</p></div><el-button @click="addOutput"><Plus/>添加输出</el-button></div><div class="structured-list"><article v-for="(o,i) in model.outputs" :key="o.id||i"><div class="list-fields output-fields"><label>客户端<el-select v-model="o.client_type"><el-option v-for="(v,k) in store.types" :key="k" :label="v.label" :value="k"/></el-select></label><label>名称<el-input v-model="o.name"/></label><label>URL 标识<el-input v-model="o.slug"/></label><label>更新间隔<el-input-number v-model="o.update_interval_minutes" :min="5" :max="10080"/></label></div><el-switch v-model="o.enabled"/><button class="icon-danger" @click="model.outputs.splice(i,1)"><Trash2/></button></article></div></section></div><aside class="editor-aside"><div class="panel sticky-card"><p class="eyebrow">V3.3 SOURCES</p><h3>统一节点来源</h3><div class="policy"><span>订阅链接</span><b>{{model.upstreams.filter(x=>x.enabled).length}}</b><span>已保存手动节点</span><b>{{manualNodes.filter(x=>x.enabled).length}}</b><span>待导入内容</span><b>{{manualContent.trim()?'有':'无'}}</b></div><p>保存后刷新一次即可建立脱敏节点快照，再进入分类管理按整条来源或单节点分配。</p></div></aside></div></section></template>
